export function FlexItem({
  grow = {{grow}},
  basis = "{{basis}}",
  alignSelf = "{{alignSelf}}",
  order = {{order}},
}) {
  const item = { background: "#A8E6C1", borderRadius: 6, padding: 10, minWidth: 40, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 600, textAlign: "center" };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="A flex row of three items; the highlighted middle item's grow, basis, align-self and order are adjustable">
      <div style={{ display: "flex", gap: 10, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 12, minHeight: 100, boxSizing: "border-box" }}>
        <div style={item}>1</div>
        <div style={{ ...item, background: "#F5C2E0", fontWeight: 700, flexGrow: grow, flexBasis: basis, alignSelf, order }}>2 (target)</div>
        <div style={item}>3</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        grow: {grow} &middot; basis: {basis} &middot; align-self: {alignSelf} &middot; order: {order}
      </p>
    </div>
  );
}
